#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>
  #include <cuda_pipeline.h>

using namespace cute;

  // C = A * B with A: (M, K) row-major, B: (K, 1)
  // Skinny-GEMV CTA tiling over M: each CTA computes Rows adjacent
  // output rows. Every vectorized B load is reused across the CTA's
  // complete M tile while the full K reduction remains inside the CTA.
  template <int Threads, int Vec, int Rows>
  __global__ __launch_bounds__(Threads)
  void matvec_cute_kernel(const float* __restrict__ A,
                          const float* __restrict__ B,
                          float* __restrict__ C,
                          int M, int K, int chunk)
  {
    const int m0  = blockIdx.x * Rows;
    const int tid = threadIdx.x;
    constexpr int TileK = Threads * Vec;
    const int k0  = blockIdx.y * chunk;
    const int k1  = min(K, k0 + chunk);
    const int len = k1 - k0;
    if (len <= 0) return;
    const int R    = len / TileK;
    const int main = R * TileK;
    const float* abase = A + (long long)m0 * (long long)K + k0;
    const float* bptr  = B + k0;
    // CuTe views of the K chunk. The final A mode is the CTA tile in M,
    // with row stride K, allowing B to be loaded once and reused for all
    // rows owned by this CTA.
    Tensor gA = make_tensor(make_gmem_ptr(abase),
                            make_shape(Int<Vec>{}, Int<Threads>{}, R, Int<Rows>{}),
                            make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}, (long long)K));
    Tensor gB = make_tensor(make_gmem_ptr(bptr),
                            make_shape(Int<Vec>{}, Int<Threads>{}, R),
                            make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}));
    Tensor tAgA = gA(_, tid, _, _);   // (Vec, R, Rows)
    Tensor tBgB = gB(_, tid, _);      // (Vec, R)
    float acc[Rows][Vec];
    #pragma unroll
    for (int r = 0; r < Rows; ++r) {
      #pragma unroll
      for (int v = 0; v < Vec; ++v) {
        acc[r][v] = 0.f;
      }
    }
    if constexpr (Vec == 8) {
      Tensor tAgA4 = recast<float4>(tAgA);   // (2, R, Rows)
      Tensor tBgB4 = recast<float4>(tBgB);   // (2, R)
      for (int j = 0; j < R; ++j) {
        const float4 b0 = tBgB4(0, j);
        const float4 b1 = tBgB4(1, j);
        #pragma unroll
        for (int r = 0; r < Rows; ++r) {
          if (m0 + r < M) {
            const float4 a0 = tAgA4(0, j, r);
            const float4 a1 = tAgA4(1, j, r);
            acc[r][0] += a0.x * b0.x;
            acc[r][1] += a0.y * b0.y;
            acc[r][2] += a0.z * b0.z;
            acc[r][3] += a0.w * b0.w;
            acc[r][4] += a1.x * b1.x;
            acc[r][5] += a1.y * b1.y;
            acc[r][6] += a1.z * b1.z;
            acc[r][7] += a1.w * b1.w;
          }
